/*---
description: NFC agrees with Node for every code point U+090000 through U+09FFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [2625171909, 1705253317, 2454614469, 1727291845, 2046120389, 4117553605, 2611741125, 1745234373, 3941589445, 1654862277, 2418981317, 2561046981, 2459732421, 3480207813, 3314663877, 3890704837];
const blocks = ["NFC U+090000-U+090FFF", "NFC U+091000-U+091FFF", "NFC U+092000-U+092FFF", "NFC U+093000-U+093FFF", "NFC U+094000-U+094FFF", "NFC U+095000-U+095FFF", "NFC U+096000-U+096FFF", "NFC U+097000-U+097FFF", "NFC U+098000-U+098FFF", "NFC U+099000-U+099FFF", "NFC U+09A000-U+09AFFF", "NFC U+09B000-U+09BFFF", "NFC U+09C000-U+09CFFF", "NFC U+09D000-U+09DFFF", "NFC U+09E000-U+09EFFF", "NFC U+09F000-U+09FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 589824 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
